// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(this));
        vm.assume(amount > 0);
        vm.prank(actor);
        try c.AdjustBetAmounts(amount) {
            assertTrue(c.currentBetLimit() == amount && actor == address(this));
        } catch {
            assertTrue(true);
        }
    }
}
